"""Aggregate daily net revenue by date and channel from a CSV file.

Usage: python daily_net.py input.csv output.csv
"""

import csv
import os
import sys
import tempfile
from datetime import datetime
from decimal import Decimal, InvalidOperation

REQUIRED_FIELDS = ["paid_at", "channel", "status", "amount", "refund_amount"]
ALLOWED_STATUS = {"PAID", "REFUNDED", "CANCELLED"}
OUTPUT_HEADER = ["date", "channel", "net_amount"]


class DataError(Exception):
    def __init__(self, row_no, field, message):
        self.row_no = row_no
        self.field = field
        self.message = message
        super().__init__(message)


class HeaderError(Exception):
    def __init__(self, field):
        self.field = field
        super().__init__(field)


def parse_amount(raw, row_no, field):
    if raw is None:
        raise DataError(row_no, field, "missing value")
    text = raw.strip()
    if text == "":
        raise DataError(row_no, field, "empty value")
    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError):
        raise DataError(row_no, field, "invalid decimal")
    if not value.is_finite():
        raise DataError(row_no, field, "non-finite value")
    if value < 0:
        raise DataError(row_no, field, "negative value")
    exponent = value.as_tuple().exponent
    if exponent < -2:
        raise DataError(row_no, field, "more than two decimal places")
    return value


def parse_date(raw, row_no):
    field = "paid_at"
    if raw is None:
        raise DataError(row_no, field, "missing value")
    text = raw.strip()
    if text == "":
        raise DataError(row_no, field, "empty value")
    try:
        parsed = datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise DataError(row_no, field, "invalid date")
    if parsed.strftime("%Y-%m-%d") != text:
        raise DataError(row_no, field, "invalid date")
    return text


def read_and_aggregate(input_path):
    totals = {}
    with open(input_path, "r", encoding="utf-8-sig", newline="") as fh:
        reader = csv.reader(fh)
        try:
            header = next(reader)
        except StopIteration:
            raise HeaderError(REQUIRED_FIELDS[0])
        header = [h.strip() for h in header]
        index = {}
        for name in REQUIRED_FIELDS:
            if name not in header:
                raise HeaderError(name)
            index[name] = header.index(name)

        row_no = 0
        for row in reader:
            row_no += 1
            if not row or (len(row) == 1 and row[0].strip() == ""):
                continue

            def get(name):
                pos = index[name]
                if pos < len(row):
                    return row[pos]
                return None

            status_raw = get("status")
            status = status_raw.strip() if status_raw is not None else ""
            if status not in ALLOWED_STATUS:
                raise DataError(row_no, "status", "unknown status")
            if status == "CANCELLED":
                continue

            date = parse_date(get("paid_at"), row_no)

            channel_raw = get("channel")
            channel = channel_raw.strip() if channel_raw is not None else ""
            if channel == "":
                raise DataError(row_no, "channel", "empty channel")

            amount = parse_amount(get("amount"), row_no, "amount")
            refund = parse_amount(get("refund_amount"), row_no, "refund_amount")
            if refund > amount:
                raise DataError(row_no, "refund_amount", "refund exceeds amount")

            net = amount - refund
            key = (date, channel)
            totals[key] = totals.get(key, Decimal("0")) + net

    return totals


def write_output(output_path, totals):
    directory = os.path.dirname(os.path.abspath(output_path)) or "."
    fd, tmp_path = tempfile.mkstemp(prefix=".daily_net_", suffix=".tmp", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as fh:
            writer = csv.writer(fh)
            writer.writerow(OUTPUT_HEADER)
            for (date, channel) in sorted(totals.keys()):
                net = totals[(date, channel)]
                writer.writerow([date, channel, format(net, ".2f")])
        os.replace(tmp_path, output_path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def main(argv):
    if len(argv) != 3:
        sys.stderr.write("usage: python daily_net.py input.csv output.csv\n")
        return 2

    input_path = argv[1]
    output_path = argv[2]

    if os.path.abspath(input_path) == os.path.abspath(output_path):
        sys.stderr.write("error: input and output paths are the same\n")
        return 2

    try:
        totals = read_and_aggregate(input_path)
    except HeaderError as exc:
        sys.stderr.write("error: missing required header field: %s\n" % exc.field)
        return 2
    except DataError as exc:
        sys.stderr.write(
            "error: row %d field %s: %s\n" % (exc.row_no, exc.field, exc.message)
        )
        return 2
    except OSError as exc:
        sys.stderr.write("error: %s\n" % exc)
        return 2

    try:
        write_output(output_path, totals)
    except OSError as exc:
        sys.stderr.write("error: %s\n" % exc)
        return 2

    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"}]}

